import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import tools.jackson.databind.ObjectMapper;
import static com.mavric.healthsqlserver.SqlServerBusinessConfigurationTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

/** Service/store composition and modeled SP dispatch, not linked-patient visibility, HTTP, JDBC or real scheduling. */
class SqlServerPortalConfigurationTest {
    static final String USER="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",PATIENT="cc000000-0000-4000-8000-000000000001",BRANCH="dd000000-0000-4000-8000-000000000001";
    static final Instant START=Instant.now().plusSeconds(3600).truncatedTo(java.time.temporal.ChronoUnit.MICROS),END=START.plusSeconds(1800);
    static class Fixture implements AutoCloseable {
        final AnnotationConfigApplicationContext context=new AnnotationConfigApplicationContext();final ObjectMapper mapper=new ObjectMapper();final Access access=mock(Access.class);final IdentityService identity=mock(IdentityService.class);final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final MockHttpServletRequest request=new MockHttpServletRequest("POST","/api/portal/appointments");final List<SqlServerProcedure> calls=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();
        Fixture(){context.getBeanFactory().registerSingleton("access",access);context.getBeanFactory().registerSingleton("identityService",identity);context.getBeanFactory().registerSingleton("settings",settings());context.getBeanFactory().registerSingleton("mapper",mapper);context.getBeanFactory().registerSingleton("sqlServerRuntimeExecutor",executor);context.getBeanFactory().registerSingleton("sqlServerRuntimeTransactionManager",manager);context.getBeanFactory().registerSingleton("sqlServerRuntimeTransactionTemplate",new org.springframework.transaction.support.TransactionTemplate(manager));context.register(SqlServerRuntimeStoresConfiguration.class,SqlServerBusinessConfiguration.class,SqlServerPortalConfiguration.class);context.refresh();var actor=new Actor(USER,"Synthetic","synthetic@example.test",TENANT,List.of("PAC"),"a".repeat(64));request.setAttribute("health.actor",actor);request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("CORE","PORTAL","FINANCE")));request.setAttribute("health.requestId",BRANCH);when(access.actor()).thenReturn(actor);TraceContext.REQUEST.set(request);when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(USER,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());var sp=inv.<SqlServerProcedure>getArgument(0);calls.add(sp);var params=Arrays.asList(((Object[])inv.getRawArguments()[2]).clone());args.add(params);Map<String,Object> row=new LinkedHashMap<>();switch(sp){case PORTAL_DOCUMENTS->{row.put("id",PATIENT);row.put("title","Synthetic");row.put("type","Synthetic");row.put("content","Synthetic content");row.put("revision",1);row.put("signerId",USER);row.put("signedAt",START.toString());row.put("contentHash","a".repeat(64));row.put("originalId",null);}case PORTAL_APPOINTMENTS->{row.put("id",PATIENT);row.put("branchId",BRANCH);row.put("professionalId",USER);row.put("specialtyCode","H_FAMILY");row.put("startsAt",START.toString());row.put("endsAt",END.toString());row.put("status","REQUESTED");row.put("service","Synthetic");row.put("revision",1);}case PORTAL_PATIENTS->{row.put("id",PATIENT);row.put("name","Synthetic");row.put("domain","HUMAN");row.put("birthDate",null);row.put("species",null);row.put("relationship","SELF");row.put("scopes",List.of("APPOINTMENTS","DOCUMENTS","BILLING"));}case PORTAL_BALANCE->{row.put("balanceMinor",-1L);row.put("currency","PEN");}case APPOINTMENT_RESERVE->{Map<?,?> body=mapper.readValue((String)params.get(1),Map.class);body.forEach((k,v)->row.put((String)k,v));row.put("id",params.getFirst());row.put("tenantId",TENANT);row.put("revision",1);row.put("requestKey",params.get(2));row.put("requestHash",params.get(3));row.put("startsAt",((String)row.get("startsAt")).replace(' ','T')+"Z");row.put("endsAt",((String)row.get("endsAt")).replace(' ','T')+"Z");assertEquals(true,params.get(4));}default->throw new AssertionError("Unexpected additional SP");}return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());});}
        PortalService portal(){return context.getBean(PortalService.class);}
        @Override public void close(){context.close();}
    }
    @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();RequestContextHolder.resetRequestAttributes();TransactionSynchronizationManager.clear();}
    @Test void fourPortalReadsAndReserveReachSelectedRealSchedulingServiceAndStores()throws Exception{try(var f=new Fixture()){assertEquals(7,((List<Map<String,Object>>)f.portal().patients()).getFirst().size());assertEquals(9,((List<Map<String,Object>>)f.portal().documents(PATIENT)).getFirst().size());assertEquals(9,((List<Map<String,Object>>)f.portal().appointments(PATIENT)).getFirst().size());assertEquals(-1L,((Map<?,?>)f.portal().balance(PATIENT)).get("balanceMinor"));var p=new Reserve(PATIENT,BRANCH,USER,"H_FAMILY",START,END,"REQUESTED","Synthetic","Synthetic note");var result=(Map<?,?>)f.portal().reserve(p,"synthetic-key-001");assertEquals(14,result.size());assertEquals("REQUESTED",result.get("status"));assertEquals(List.of(SqlServerProcedure.PORTAL_PATIENTS,SqlServerProcedure.PORTAL_DOCUMENTS,SqlServerProcedure.PORTAL_APPOINTMENTS,SqlServerProcedure.PORTAL_BALANCE,SqlServerProcedure.APPOINTMENT_RESERVE),f.calls);assertEquals(List.of(),f.args.getFirst());for(int index=1;index<4;index++)assertEquals(List.of(PATIENT),f.args.get(index));assertEquals(5,f.args.getLast().size());assertEquals(true,f.args.getLast().getLast());assertSame(f.context.getBean(SchedulingService.class),field(f.portal(),"scheduling"));assertFalse(mockingDetails(f.context.getBean(SchedulingService.class)).isMock());assertSame(f.context.getBean(SqlServerSchedulingStore.class),field(f.context.getBean(SchedulingService.class),"store"));verify(f.access).link(PATIENT,"APPOINTMENTS");verify(f.access,never()).branch(anyString());assertEquals(5,Collections.frequency(f.manager.events,"commit"));assertTrue(f.context.getBeansOfType(com.mavric.health.shared.Sql.class).isEmpty());verifyNoInteractions(f.identity);}}
    @Test void spErrorPropagatesWithoutFallbackAndRequestAuthorityIsRetained(){try(var f=new Fixture()){var actor=f.request.getAttribute("health.actor");var host=f.request.getAttribute("health.tenant");doThrow(new RuntimeException(new java.sql.SQLException("private-canary",null,51001))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->f.portal().documents(PATIENT));assertEquals(403,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("private-canary"));verify(f.executor,times(1)).execute(eq(SqlServerProcedure.PORTAL_DOCUMENTS),any(),eq(PATIENT));assertSame(actor,f.request.getAttribute("health.actor"));assertSame(host,f.request.getAttribute("health.tenant"));assertSame(f.request,TraceContext.REQUEST.get());}}
    @Test void allFourStoresAndSchedulingAreRequiredAndQualifiersIgnoreDecoys()throws Exception{var types=List.of(SqlServerPortalDocumentStore.class,SqlServerPortalAppointmentStore.class,SqlServerPortalPatientsStore.class,SqlServerPortalBalanceStore.class);for(String missing:List.of("sqlServerPortalDocumentStore","sqlServerPortalAppointmentStore","sqlServerPortalPatientsStore","sqlServerPortalBalanceStore","schedulingService","access","none")){var deps=new LinkedHashMap<String,Object>();for(Class<?> type:types)deps.put(name(type),mock(type));deps.put("access",mock(Access.class));deps.put("schedulingService",mock(SchedulingService.class));deps.remove(missing);var decoy=mock(SqlServerPortalDocumentStore.class);try(var context=new AnnotationConfigApplicationContext()){deps.forEach((key,value)->context.getBeanFactory().registerSingleton(key,value));context.getBeanFactory().registerSingleton("otherDocumentStore",decoy);context.register(SqlServerPortalConfiguration.class);if(missing.equals("none")){context.refresh();assertSame(deps.get("sqlServerPortalDocumentStore"),field(context.getBean(PortalService.class),"store"));assertNull(field(context.getBean(PortalService.class),"sql"));}else assertThrows(RuntimeException.class,context::refresh);verifyNoInteractions(decoy);}}}
    @Test void portalFactoryIsCompleteAndNoAutomaticImportOrLegacyScanning(){assertEquals(1,SqlServerPortalConfiguration.class.getDeclaredAnnotations().length);assertFalse(SqlServerPortalConfiguration.class.getAnnotation(Configuration.class).proxyBeanMethods());var methods=Arrays.stream(SqlServerPortalConfiguration.class.getDeclaredMethods()).filter(method->method.isAnnotationPresent(Bean.class)).toList();assertEquals(1,methods.size());assertEquals(PortalService.class,methods.getFirst().getReturnType());assertTrue(new ClassPathScanningCandidateComponentProvider(true).findCandidateComponents("com.mavric.health").stream().noneMatch(bean->bean.getBeanClassName().startsWith("com.mavric.healthsqlserver.")));}
}
